import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

const corsHeaders = {
  'Access-Control-Allow-Origin': 'https://reservas.balneariolessa.com.br',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-client-info',
  'Access-Control-Allow-Methods': 'POST, GET, OPTIONS, PUT, DELETE',
  'Access-Control-Max-Age': '86400',
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response(null, { headers: corsHeaders, status: 204 })
  }

  try {
    const body = await req.json()
    const {
      name, phone, cpf, visit_date, status,
      adults_normal = 0, adults_half = 0,
      is_teacher = 0, is_student = 0, is_server = 0,
      is_donor = 0, is_solidarity = 0,
      is_pcd = 0, is_tea = 0, is_senior = 0, is_birthday = 0,
      children_free = 0,
      selected_kiosks = [],
      quads = [],
      manual_discount = 0,
      manual_discount_type = 'unit',
      total_amount = 0
    } = body

    if (!name || !visit_date) {
      return new Response(JSON.stringify({ success: false, error: 'Nome e data são obrigatórios' }), {
        headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 400
      })
    }

    const supabase = createClient(
      Deno.env.get('SUPABASE_URL') || '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') || ''
    )

    const orderStatus = status === 'paid' ? 'paid' : 'pending'
    const { data: order, error: orderError } = await supabase
      .from('orders')
      .insert({
        customer_name: name.trim(),
        customer_phone: phone || null,
        customer_cpf: cpf || null,
        visit_date,
        total_amount,
        status: orderStatus,
        updated_at: new Date().toISOString()
      })
      .select('id, confirmation_code')
      .single()

    if (orderError) throw orderError
    const orderId = order.id

    const items: any[] = []
    const addItem = (product_id: string, quantity: number, unit_price: number) => {
      if (quantity > 0) items.push({ order_id: orderId, product_id, quantity, unit_price })
    }

    addItem('Adulto', adults_normal, 50)
    addItem('Meia-Entrada', adults_half, 25)
    addItem('Lessa Professor Pass', is_teacher, 25)
    addItem('Lessa Estudante Pass', is_student, 25)
    addItem('Lessa Servidor Pass', is_server, 25)
    addItem('Lessa Doador Pass', is_donor, 25)
    addItem('Adulto Solidário', is_solidarity, 25)
    addItem('Lessa Inclusão', is_pcd, 0)
    addItem('Lessa TEA', is_tea, 0)
    addItem('Lessa Vitalício', is_senior, 0)
    addItem('Aniversariante', is_birthday, 0)
    addItem('Criança', children_free, 0)

    selected_kiosks.forEach((id: number) => {
      addItem(`Quiosque ${String(id).padStart(2, '0')}`, 1, id === 1 ? 100 : 75)
    })

    const dayOfWeek = new Date(visit_date + 'T12:00:00').getDay()
    let qDisc = (dayOfWeek === 1 || dayOfWeek === 5) ? 0.2 : (dayOfWeek === 0 || dayOfWeek === 6 ? 0.1 : 0)

    quads.forEach((q: any) => {
      if (q.quantity <= 0) return
      const baseMap: any = { individual: 150, dupla: 250, 'adulto-crianca': 200 }
      const unitP = baseMap[q.type] * (1 - qDisc)
      items.push({
        order_id: orderId,
        product_id: `Quadriciclo ${q.type}`,
        quantity: q.quantity,
        unit_price: unitP,
        metadata: { time: q.time }
      })
    })

    if (items.length > 0) await supabase.from('order_items').insert(items)

    if (selected_kiosks.length > 0) {
      const kR = selected_kiosks.map((id: number) => ({
        order_id: orderId, kiosk_id: id, kiosk_type: id === 1 ? 'maior' : 'menor', reservation_date: visit_date, quantity: 1, customer_name: name.trim()
      }))
      await supabase.from('kiosk_reservations').insert(kR)
    }

    const activeQuads = quads.filter((q: any) => q.quantity > 0 && q.time)
    if (activeQuads.length > 0) {
      const qR = activeQuads.map((q: any) => ({ 
        order_id: orderId, quad_type: q.type, reservation_date: visit_date, time_slot: q.time, quantity: q.quantity, customer_name: name.trim()
      }))
      await supabase.from('quad_reservations').insert(qR)
    }

    let pix = null
    if (orderStatus === 'pending') {
      try {
        const KEY = Deno.env.get('ASAAS_API_KEY')
        if (KEY) {
          const URL = KEY.startsWith('aact_live_') ? 'https://www.asaas.com/api/v3' : 'https://sandbox.asaas.com/api/v3'
          const cReq = await fetch(`${URL}/customers`, { method: 'POST', headers: { 'access_token': KEY, 'Content-Type': 'application/json' }, body: JSON.stringify({ name: name.trim() }) })
          const cData = await cReq.json()
          if (cReq.ok) {
            const pReq = await fetch(`${URL}/payments`, { method: 'POST', headers: { 'access_token': KEY, 'Content-Type': 'application/json' }, body: JSON.stringify({ customer: cData.id, billingType: 'PIX', value: total_amount, dueDate: new Date().toISOString().split('T')[0], description: `Reserva - ${name.trim()}` }) })
            const pData = await pReq.json()
            if (pReq.ok) {
              const qrReq = await fetch(`${URL}/payments/${pData.id}/pixQrCode`, { headers: { 'access_token': KEY } })
              const qrData = await qrReq.json()
              if (qrReq.ok) pix = { encodedImage: qrData.encodedImage, payload: qrData.payload }
              await supabase.from('payments').insert({ order_id: orderId, gateway: 'asaas', metodo: 'PIX', status: 'pending', external_id: pData.id })
            }
          }
        }
      } catch (e) { console.error(e) }
    }

    if (orderStatus === 'paid') {
      const code = `BL-${Math.random().toString(36).substring(2, 8).toUpperCase()}`
      await supabase.from('vouchers').insert({ order_id: orderId, code, status: 'active', created_at: new Date().toISOString() })
    }

    return new Response(JSON.stringify({ success: true, orderId, pix }), { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 })

  } catch (err: any) {
    return new Response(JSON.stringify({ success: false, error: err.message }), { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 })
  }
})
